scripts:
var isFirst = true;

$(document).ready( function() {
	jQuery.ajaxSetup({async:false, cache: false});
	$("#wrap").css('display', 'block');
	$('#cbo_Smst').val('2');

	$('#edt_Shyr, #cbo_Smst').change(function() {
		// 1. 기존 그리드 데이터 초기화
		if ($("#grd_ScheduleMain").jqGrid('getGridParam', 'reccount') !== undefined) {
			$('#grd_ScheduleMain').clearGridData();
			$('#grdCnt').text('총 0건');
		}

		// 2. 변경된 학년도/학기 기준으로 학과 콤보박스 갱신
		refreshLessCombo();
	});

	// 조회 버튼 설정
	$('#btn_ReportSearch').click(function(e){

		if ($('#cbo_Smst').val() == '1' || $('#cbo_Smst').val() == '2') {
			if($('#cbo_Less').val() == '') {
		        if($('#edt_SubjNm').val().length < 2) {
					alert(setLabel('전체 학과로 조회 시 교과목명을 2자이상 입력 하세요.', 'Put at least 2 characters in the subject line to search within the database.'));
					return;
				}
			}		
		}

		var maxYmst = '20262';

		if ('20262' != '') {
			var sYmst = Number($('#edt_Shyr').val() + $('#cbo_Smst').val());
			maxYmst = Number(maxYmst);

			if (maxYmst % 2 == 0) {
				maxYmst = maxYmst + 2;
			}

			if (sYmst % 2 == 0) {
				sYmst = sYmst + 2;
			}

			if (sYmst > maxYmst) {
				var hak = $('#cbo_Smst').val();

				if (hak == '3') {
					hak = '여름'
				} else if (hak == '4') {
					hak = '겨울'
				}

				var msg = $('#edt_Shyr').val() + '학년도 ' + hak + '학기 시간표는 조회 할 수 없습니다.';
				alert(msg);
				return ;

			}

		}

		document.body.style.cursor = 'wait';
		$('#btn_ReportSearch').hide();

		if (isFirst) {
			setTimeout(
				function() {
					writeScheduleGrid();
					isFirst = false;
				}, 10
			);

		} else {
			setTimeout(
				function() {
					var param = {
							'fsp_action' : 'GridAction'
							, 'fsp_cmd' : 'getScheduleGridData'
							, 'SP_YMST' : $('#edt_Shyr').val() + $('#cbo_Smst').val()
							, 'LESS_CD' : $('#cbo_Less').val()
							, 'DN_DIV' : $('#cbo_DnDiv').val()
							, 'SUBJ_NM' : $('#edt_SubjNm').val()
							, 'LECT_DIV' : $('#cbo_Gbn').val()
							, 'DOTW_CD' : $('#cbo_Days').val()
					};
					$('#grd_ScheduleMain').reloadGrid(param);
				}, 10
			);
		}

	});

	$('#cbo_lang').change(function(e){
		setLanguage($('#cbo_lang').val());
		setGridColumn();

		refreshLessCombo();

	});

	if ('' == 'en') {
		$("#cbo_lang").val("en").prop("selected", true).trigger('change');
		$('#cbo_Gbn').val('eng');
	} else if ('' == 'ko') {
		$("#cbo_lang").val("en").prop("selected", true).trigger('change');

	} else {
		$("#cbo_lang").val(getLanguage()).prop("selected", true).trigger('change');
	}

	// 다국어 적용 끝
});

function refreshLessCombo() {
	// 현재 화면에 입력된 년도(4자리)와 학기(1자리)를 조합하여 ymst 생성
	var currentYmst = $('#edt_Shyr').val() + $('#cbo_Smst').val();

	if(!$('#edt_Shyr').val() || !$('#cbo_Smst').val()) return;

	$.getJSON($.consts.CONTEXT_PATH + 'json/combo/' + currentYmst + '/less/less.json', function(data) {
		$('#cbo_Less').empty();
		$('#cbo_Less').append('<option value=""> = ' + setLabel('전체', 'All') + ' =</option>');

		$.each(data, function() {
			if (this.ORGN_LEVEL == 2) {
				$('#cbo_Less').append($('<option>').val(this.ORGN_CD).text('- ' + setLabel(this.ORGN_NM.rPad(50, '-'), this.ORGN_ENM.rPad(50, '-'))));
			} else {
				$('#cbo_Less').append($('<option>').val(this.ORGN_CD).text(' ' + setLabel(this.ORGN_NM, this.ORGN_ENM)));
			}
		});
	}).fail(function() {
		// JSON 파일이 없을 경우 DB에서 직접 조회하는 백업 로직 호출
		$('#cbo_Less').empty();
		$('#cbo_Less').append('<option value=""> = ' + setLabel('전체', 'All') + ' =</option>');
		$.setLessCommboToDb(currentYmst, 'cbo_Less');
	});
}

function setGridColumn() {
	if($('#cbo_lang').val() == 'ko') {
		$("#grd_ScheduleMain").showCol('SUBJ_KNM');
		$('#grd_ScheduleMain').hideCol('SUBJ_ENM');

		$("#grd_ScheduleMain").showCol('SP_LESS_CD_NM');
		$('#grd_ScheduleMain').hideCol('SP_LESS_CD_ENM');

		$("#grd_ScheduleMain").showCol('MNG_LESS_NM');
		$('#grd_ScheduleMain').hideCol('MNG_LESS_ENM');

		$("#grd_ScheduleMain").showCol('CMPT_DIV_NM');
		$('#grd_ScheduleMain').hideCol('CMPT_DIV_ENM');

		$("#grd_ScheduleMain").showCol('PROF_NM');
		$('#grd_ScheduleMain').hideCol('PROF_ENM');

		$("#grd_ScheduleMain").showCol('LSTM_LIST');
		$('#grd_ScheduleMain').hideCol('LSTM_LIST_ENM');

		$("#grd_ScheduleMain").showCol('BLDG_COUM');
		$('#grd_ScheduleMain').hideCol('BLDG_COUM_ENM');

		$("#grd_ScheduleMain").showCol('ETC');
		$('#grd_ScheduleMain').hideCol('ETC_ENM');

		$("#grd_ScheduleMain").showCol('COUR_LANG');
		$('#grd_ScheduleMain').hideCol('COUR_LANG_ENM');

		$('#btn_ReportSearch').removeClass('btn_crud_search_e');
		$('#btn_ReportSearch').addClass('btn_crud_search');

	} else {
		$("#grd_ScheduleMain").showCol('SUBJ_ENM');
		$('#grd_ScheduleMain').hideCol('SUBJ_KNM');

		$("#grd_ScheduleMain").showCol('SP_LESS_CD_ENM');
		$('#grd_ScheduleMain').hideCol('SP_LESS_CD_NM');

		$("#grd_ScheduleMain").showCol('MNG_LESS_ENM');
		$('#grd_ScheduleMain').hideCol('MNG_LESS_NM');

		$("#grd_ScheduleMain").showCol('CMPT_DIV_ENM');
		$('#grd_ScheduleMain').hideCol('CMPT_DIV_NM');

		$("#grd_ScheduleMain").showCol('PROF_ENM');
		$('#grd_ScheduleMain').hideCol('PROF_NM');

		$("#grd_ScheduleMain").showCol('LSTM_LIST_ENM');
		$('#grd_ScheduleMain').hideCol('LSTM_LIST');

		$("#grd_ScheduleMain").showCol('BLDG_COUM_ENM');
		$('#grd_ScheduleMain').hideCol('BLDG_COUM');

		$("#grd_ScheduleMain").showCol('ETC_ENM');
		$('#grd_ScheduleMain').hideCol('ETC');

		$("#grd_ScheduleMain").showCol('COUR_LANG_ENM');
		$('#grd_ScheduleMain').hideCol('COUR_LANG');

		$('#btn_ReportSearch').removeClass('btn_crud_search');
		$('#btn_ReportSearch').addClass('btn_crud_search_e');

	}

	$("#grd_ScheduleMain").jqGrid('setGridWidth', ($.windowWidth($.consts.BASE_WIDTH)-8));
}


function writeScheduleGrid() {

	var param = {
			'fsp_action' : 'GridAction'
			, 'fsp_cmd' : 'getScheduleGridData'
			, 'SP_YMST' : $('#edt_Shyr').val() + $('#cbo_Smst').val()
			, 'LESS_CD' : $('#cbo_Less').val()
			, 'DN_DIV' : $('#cbo_DnDiv').val()
			, 'SUBJ_NM' : $('#edt_SubjNm').val()
			, 'LECT_DIV' : $('#cbo_Gbn').val()
			, 'DOTW_CD' : $('#cbo_Days').val()
	};



	jQuery("#grd_ScheduleMain").jqGrid({
		url:fsp.serverUrl
		, ajaxGridOptions: {
			cache: false,
			contentType: "application/json",
			processData: false,
			type: "POST"
		}
	   	, postData :$.toJSON(param )
		, datatype: "json"
		, colModel: $.gridheader.scheduleList
		, height: 600
		, rowNum: -1
	    , viewrecords: true
	    , rownumbers: true
	    , gridview: false
	    , loadComplete : function(data) {
			 if(data.records == 0){
                $("#" + $(this).attr('id') + " >tbody").append("<tr><td align='center' colspan='" + $.gridheader.scheduleList.length  + "'>검색 결과가 없습니다.</td></tr>");
            }
			orgData = data;
			$('#grdCnt').text('총 '+data.records+'건');
		}
	   	, beforeRequest : function() {
	   		//alert('test');
	   		document.body.style.cursor = 'wait';
	   		$('#btn_ReportSearch').hide();
	   	}
	   	, gridComplete: function(){
	   		document.body.style.cursor = 'auto';
	   		$('#btn_ReportSearch').show();

	   		setLanguage($('#cbo_lang').val());
	   		setGridColumn();

	    	var dataIds = $('#grd_ScheduleMain').jqGrid('getDataIDs');
	    	$('#grdCnt').text('총 ' + dataIds.length + '건');
	    	$('#grdTitle').text($('#edt_Shyr').val() + ' / ' + $('#cbo_Smst option:selected').text());
	    }
	   	, ondblClickRow: function(rowid) {
			rowData = orgData.rows[rowid-1];

			if (rowData.PROG_YN == 'Y') {
				var pram = "?ymst=" + $('#edt_Shyr').val() + $('#cbo_Smst').val() + "&subjCd=" + rowData.SUBJ_CD + "&lectNumb=" + rowData.LECT_NUMB + "&profNumb=" + rowData.PROF_NUMB;
				var wind;
				var width = 930;
				var height = 800;

				if (rowData.ABEEK_YN == 'Y') {
					wind = window.open("/html/program_popup01.html" + pram, "wind", 'top='+((screen.availHeight - height)/2 - 40) +', left='+(screen.availWidth - width)/2+', width='+width+', height='+height+', toolbar=0, directories=0, status=0, menubar=0, scrollbars=yes, resizable=0');
				} else {
					wind = window.open("/html/program_popup02.html" + pram, "wind", 'top='+((screen.availHeight - height)/2 - 40) +', left='+(screen.availWidth - width)/2+', width='+width+', height='+height+', toolbar=0, directories=0, status=0, menubar=0, scrollbars=yes, resizable=0');
				}

				wind.focus();
			} else {
				alert("등록된 강의계획서가 없습니다.")
			}


		}
	}); 

	$(window).bind('resize', function() {
		$("#grd_ScheduleMain").jqGrid('setGridWidth', ($.windowWidth($.consts.BASE_WIDTH)-8));
		$("#grd_ScheduleMain").jqGrid('setGridHeight', ($.windowHeight(600)-240));
	}).trigger('resize');
}

function viewSy(PROG_YN, ABEEK_YN, SUBJ_CD, LECT_NUMB, PROF_NUMB) {

	if (PROG_YN == 'Y') {
		var pram = "?ymst=" + $('#edt_Shyr').val() + $('#cbo_Smst').val() + "&subjCd=" + SUBJ_CD + "&lectNumb=" + LECT_NUMB + "&profNumb=" + PROF_NUMB;
		var wind;
		var width = 930;
		var height = 800;

		if (ABEEK_YN == 'Y') {
			wind = window.open("/view/program_popup01.jsp" + pram, "wind", 'top='+((screen.availHeight - height)/2 - 40) +', left='+(screen.availWidth - width)/2+', width='+width+', height='+height+', toolbar=0, directories=0, status=0, menubar=0, scrollbars=yes, resizable=0');
		} else {
			wind = window.open("/view/program_popup02.jsp" + pram, "wind", 'top='+((screen.availHeight - height)/2 - 40) +', left='+(screen.availWidth - width)/2+', width='+width+', height='+height+', toolbar=0, directories=0, status=0, menubar=0, scrollbars=yes, resizable=0');
		}

		wind.focus();
	} else {
		alert("등록된 강의계획서가 없습니다.")
	}
}
